content.text:
import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import {
  requireAuth,
  requireAdmin,
  sanitizeUser,
  networkDelay,
} from '../utils';

type ProfileBody = {
  email: string;
  firstName: string;
  lastName: string;
  bio: string;
};

type UpdateUserRoleBody = {
  role: 'ADMIN' | 'USER';
};

export const usersHandlers = [
  http.get(`${env.API_URL}/users`, async ({ cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const result = db.user
        .findMany({
          where: {
            teamId: {
              equals: user?.teamId,
            },
          },
        })
        .map(sanitizeUser);

      return HttpResponse.json({ data: result });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(`${env.API_URL}/users/profile`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const data = (await request.json()) as ProfileBody;
      const result = db.user.update({
        where: {
          id: {
            equals: user?.id,
          },
        },
        data,
      });
      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(
    `${env.API_URL}/users/:userId/role`,
    async ({ request, cookies, params }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        requireAdmin(user);
        const userId = params.userId as string;
        const data = (await request.json()) as UpdateUserRoleBody;

        const result = db.user.update({
          where: {
            id: {
              equals: userId,
            },
            teamId: {
              equals: user?.teamId,
            },
          },
          data: { role: data.role },
        });
        await persistDb('user');
        return HttpResponse.json(sanitizeUser(result));
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),

  http.delete(`${env.API_URL}/users/:userId`, async ({ cookies, params }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const userId = params.userId as string;
      requireAdmin(user);
      const result = db.user.delete({
        where: {
          id: {
            equals: userId,
          },
          teamId: {
            equals: user?.teamId,
          },
        },
      });
      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
];

import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';

import { useUsers } from '../api/get-users';

import { DeleteUser } from './delete-user';
import { UpdateUserRole } from './update-user-role';

export const UsersList = () => {
  const usersQuery = useUsers();

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry: { id, role } }) {
            return <UpdateUserRole userId={id} currentRole={role} />;
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';

import { getUsersQueryOptions } from './get-users';

export const updateUserRoleInputSchema = z.object({
  role: z.enum(['ADMIN', 'USER']),
});

export type UpdateUserRoleInput = z.infer<typeof updateUserRoleInputSchema>;

export type UpdateUserRoleDTO = {
  userId: string;
  data: UpdateUserRoleInput;
};

export const updateUserRole = ({ userId, data }: UpdateUserRoleDTO) => {
  return api.patch(`/users/${userId}/role`, data);
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getUsersQueryOptions().queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};

import { Check, ChevronDown } from 'lucide-react';
import { useState } from 'react';

import { useNotifications } from '@/components/ui/notifications';

import { UpdateUserRoleInput } from '../api/update-user-role';
import { useUpdateUserRole } from '../api/update-user-role';

type UpdateUserRoleProps = {
  userId: string;
  currentRole: 'ADMIN' | 'USER';
};

const ROLES: { value: 'ADMIN' | 'USER'; label: string }[] = [
  { value: 'ADMIN', label: 'Admin' },
  { value: 'USER', label: 'User' },
];

export const UpdateUserRole = ({ userId, currentRole }: UpdateUserRoleProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [selectedRole, setSelectedRole] = useState<'ADMIN' | 'USER'>(currentRole);
  const { addNotification } = useNotifications();
  const updateUserRoleMutation = useUpdateUserRole({
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'User role updated',
        });
        setIsOpen(false);
      },
    },
  });

  const handleSelectRole = (role: 'ADMIN' | 'USER') => {
    if (role === selectedRole) {
      setIsOpen(false);
      return;
    }
    setSelectedRole(role);
    setIsSaving(true);
    updateUserRoleMutation.mutate({
      userId,
      data: { role },
    });
  };

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        disabled={isSaving || updateUserRoleMutation.isPending}
        className="flex items-center gap-1 rounded-md border border-gray-300 bg-white px-2 py-1 text-sm text-gray-700 hover:bg-gray-50"
      >
        <span>{selectedRole}</span>
        {isOpen ? (
          <ChevronDown className="size-4 text-gray-500" />
        ) : (
          <Check className="size-4 text-gray-500" />
        )}
      </button>

      {isOpen && (
        <>
          <div
            className="fixed inset-0 z-10"
            onClick={() => setIsOpen(false)}
          />
          <div className="absolute left-0 z-20 mt-1 w-32 origin-top-left rounded-md border border-gray-200 bg-white py-1 shadow-lg">
            {ROLES.map((role) => (
              <button
                key={role.value}
                type="button"
                onClick={() => handleSelectRole(role.value)}
                className={`w-full px-3 py-1.5 text-left text-sm ${
                  selectedRole === role.value
                    ? 'bg-gray-100 font-medium text-gray-900'
                    : 'text-gray-700 hover:bg-gray-50'
                }`}
              >
                {role.label}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};
